  },
  danger: {
    text: '#FF453A',
  },
  overlayScrim: 'rgba(0,0,0,0.6)',
};

export type Theme = typeof lightTokens;

export function useTheme(): { theme: Theme; isDark: boolean } {
  const scheme = useColorScheme();
  const isDark = scheme === 'dark';
  return { theme: isDark ? darkTokens : lightTokens, isDark };
}
