// SettingsRow.tsx
import React from 'react';
import {
  View,
  Text,
  Pressable,
  Switch,
  StyleSheet,
  ActivityIndicator,
  Platform,
} from 'react-native';
import { Theme } from './theme';

type BaseRowProps = {
  theme: Theme;
  label: string;
  subtitle?: string;
  destructive?: boolean;
  disabled?: boolean;
  testID?: string;
};

type NavigationRowProps = BaseRowProps & {
  kind: 'navigation';
  onPress: () => void;
  value?: string;
  loading?: boolean;
};

type ToggleRowProps = BaseRowProps & {
  kind: 'toggle';
  value: boolean;
  onValueChange: (next: boolean) => void;
};

export type SettingsRowProps = NavigationRowProps | ToggleRowProps;

export function SettingsRow(props: SettingsRowProps) {
  const { theme, label, subtitle, destructive, disabled } = props;

  const content = (
    <View style={styles.rowInner}>
      <View style={styles.rowTextGroup}>
        <Text
          style={[
            styles.label,
            { color: destructive ? theme.danger.text : theme.text.primary },
            disabled && styles.disabledText,
          ]}
          allowFontScaling
        >
          {label}
        </Text>
        {subtitle ? (
          <Text
            style={[styles.subtitle, { color: theme.text.secondary }]}
            allowFontScaling
          >
            {subtitle}
          </Text>
        ) : null}
      </View>

      {props.kind === 'toggle' ? (
        <Switch
          value={props.value}
          onValueChange={props.onValueChange}
          disabled={disabled}
          accessibilityLabel={label}
        />
      ) : (
        <View style={styles.trailing}>
          {props.loading ? (
            <ActivityIndicator size="small" color={theme.text.secondary} />
          ) : (
            <>
              {props.value ? (
                <Text style={[styles.value, { color: theme.text.secondary }]}>
                  {props.value}
                </Text>
              ) : null}
              {!destructive ? (
                <Text style={[styles.chevron, { color: theme.text.secondary }]}>
                  {'\u203A'}
                </Text>
              ) : null}
            </>
          )}
        </View>
      )}
    </View>
  );

  if (props.kind === 'toggle') {
    // Entire row is informational; the Switch itself is the interactive control.
    return (
      <View
        style={[styles.row, { minHeight: 48, backgroundColor: theme.bg.surface }]}
        testID={props.testID}
      >
        {content}
      </View>
    );
  }

  return (
    <Pressable
      onPress={props.onPress}
      disabled={disabled || props.loading}
      accessibilityRole="button"
      accessibilityLabel={label}
      accessibilityHint={subtitle}
      accessibilityState={{ disabled: !!disabled }}
      android_ripple={{ color: theme.border.subtle }}
      style={({ pressed }) => [
        styles.row,
        { minHeight: 48, backgroundColor: theme.bg.surface },
        Platform.OS === 'ios' && pressed && { backgroundColor: theme.bg.surfaceRaised },
        (disabled || props.loading) && styles.disabledRow,
      ]}
      testID={props.testID}
    >
      {content}
    </Pressable>
  );
}

export function SectionHeader({ title, theme }: { title: string; theme: Theme }) {
  return (
    <Text style={[styles.sectionHeader, { color: theme.text.secondary }]}>
      {title.toUpperCase()}
    </Text>
  );
}

export function Divider({ theme }: { theme: Theme }) {
  return <View style={[styles.divider, { backgroundColor: theme.border.subtle }]} />;
}

const styles = StyleSheet.create({
  row: {
    paddingHorizontal: 16,
    paddingVertical: 10,
    justifyContent: 'center',
  },
  disabledRow: {
    opacity: 0.5,
  },
  rowInner: {
    flexDirection: 'row',
    alignItems: 'center',
    justifyContent: 'space-between',
  },
  rowTextGroup: {
    flex: 1,
    marginRight: 12,
  },
  label: {
    fontSize: 16,
  },
  subtitle: {
    fontSize: 13,
    marginTop: 2,
  },
  disabledText: {
    opacity: 0.6,
  },
  trailing: {
    flexDirection: 'row',
    alignItems: 'center',
  },
  value: {
    fontSize: 15,
    marginRight: 4,
  },
  chevron: {
    fontSize: 20,
    marginLeft: 2,
  },
  sectionHeader: {
    fontSize: 12,
    fontWeight: '600',
    letterSpacing: 0.4,
    marginHorizontal: 16,
    marginBottom: 6,
    marginTop: 20,
  },
  divider: {
    height: 1,
    marginLeft: 16,
  },
});
