// Avatar.tsx
import React from 'react';
import { View, Text, Image, StyleSheet } from 'react-native';
import { Theme } from './theme';

type AvatarProps = {
  theme: Theme;
  name: string;
  imageUri?: string;
  size?: number;
};

export function Avatar({ theme, name, imageUri, size = 56 }: AvatarProps) {
  const initials = name
    .trim()
    .split(/\s+/)
    .slice(0, 2)
    .map((part) => part[0]?.toUpperCase())
    .join('');

  if (imageUri) {
    return (
      <Image
        source={{ uri: imageUri }}
        style={[styles.image, { width: size, height: size, borderRadius: size / 2 }]}
        accessibilityIgnoresInvertColors
      />
    );
  }

  return (
    <View
      style={[
        styles.fallback,
        {
          width: size,
          height: size,
          borderRadius: size / 2,
          backgroundColor: theme.accent.solid,
        },
      ]}
    >
      <Text style={[styles.initials, { color: theme.text.onAccent, fontSize: size * 0.36 }]}>
        {initials || '?'}
      </Text>
    </View>
  );
}

const styles = StyleSheet.create({
  image: {
    backgroundColor: '#00000010',
  },
  fallback: {
    alignItems: 'center',
    justifyContent: 'center',
  },
  initials: {
    fontWeight: '600',
  },
});
