// AccountSettingsScreen.tsx
import React, { useState, useCallback } from 'react';
import {
  View,
  Text,
  ScrollView,
  Pressable,
  Alert,
  StyleSheet,
  StatusBar,
  Platform,
} from 'react-native';
import { useSafeAreaInsets } from 'react-native-safe-area-context';
import { useTheme } from './theme';
import { SettingsRow, SectionHeader, Divider } from './SettingsRow';
import { Avatar } from './Avatar';

type User = {
  name: string;
  email: string;
  avatarUri?: string;
};

export type AccountSettingsScreenProps = {
  user: User;
  notificationsEnabled: boolean;
  biometricLoginEnabled: boolean;
  onEditProfile: () => void;
  onChangePassword: () => void;
  onChangeNotifications: (next: boolean) => void;
  onChangeBiometricLogin: (next: boolean) => void;
  onOpenPrivacy: () => void;
  onOpenHelp: () => void;
  onSignOut: () => void;
  /** Should reject on failure; resolve on success. */
  onDeleteAccount: () => Promise<void>;
};

export function AccountSettingsScreen({
  user,
  notificationsEnabled,
  biometricLoginEnabled,
  onEditProfile,
  onChangePassword,
  onChangeNotifications,
  onChangeBiometricLogin,
  onOpenPrivacy,
  onOpenHelp,
  onSignOut,
  onDeleteAccount,
}: AccountSettingsScreenProps) {
  const { theme, isDark } = useTheme();
  const insets = useSafeAreaInsets();
  const [isDeleting, setIsDeleting] = useState(false);

  const confirmDelete = useCallback(() => {
    if (isDeleting) return;

    Alert.alert(
      'Delete account',
      'This permanently deletes your account and all associated data. This action cannot be undone.',
      [
        { text: 'Cancel', style: 'cancel' },
        {
          text: 'Delete',
          style: 'destructive',
          onPress: async () => {
            setIsDeleting(true);
            try {
              await onDeleteAccount();
            } catch (error) {
              setIsDeleting(false);
              Alert.alert(
                'Couldn\u2019t delete account',
                'Something went wrong. Please check your connection and try again.',
              );
            }
          },
        },
      ],
    );
  }, [isDeleting, onDeleteAccount]);

  return (
    <View style={[styles.flex, { backgroundColor: theme.bg.app }]}>
      <StatusBar
        barStyle={isDark ? 'light-content' : 'dark-content'}
        backgroundColor={theme.bg.app}
      />
      <ScrollView
        style={styles.flex}
        contentContainerStyle={{
          paddingTop: insets.top + 12,
          paddingBottom: insets.bottom + 32,
          paddingLeft: insets.left,
          paddingRight: insets.right,
        }}
        contentInsetAdjustmentBehavior="automatic"
      >
        <Text style={[styles.screenTitle, { color: theme.text.primary }]}>
          Account
        </Text>

        {/* Profile row */}
        <Pressable
          onPress={onEditProfile}
          accessibilityRole="button"
          accessibilityLabel={`${user.name}, ${user.email}`}
          accessibilityHint="Edit profile"
          android_ripple={{ color: theme.border.subtle }}
          style={({ pressed }) => [
            styles.profileRow,
            { backgroundColor: theme.bg.surface, minHeight: 48 },
            Platform.OS === 'ios' && pressed && { backgroundColor: theme.bg.surfaceRaised },
          ]}
        >
          <Avatar theme={theme} name={user.name} imageUri={user.avatarUri} />
          <View style={styles.profileText}>
            <Text style={[styles.profileName, { color: theme.text.primary }]} numberOfLines={1}>
              {user.name}
            </Text>
            <Text style={[styles.profileEmail, { color: theme.text.secondary }]} numberOfLines={1}>
              {user.email}
            </Text>
          </View>
          <Text style={[styles.chevron, { color: theme.text.secondary }]}>{'\u203A'}</Text>
        </Pressable>

        {/* Preferences */}
        <SectionHeader title="Preferences" theme={theme} />
        <View style={[styles.sectionGroup, { backgroundColor: theme.bg.surface }]}>
          <SettingsRow
            kind="toggle"
            theme={theme}
            label="Notifications"
            value={notificationsEnabled}
            onValueChange={onChangeNotifications}
          />
          <Divider theme={theme} />
          <SettingsRow
            kind="toggle"
            theme={theme}
            label="Biometric login"
            subtitle={Platform.OS === 'ios' ? 'Use Face ID or Touch ID' : 'Use fingerprint or face unlock'}
            value={biometricLoginEnabled}
            onValueChange={onChangeBiometricLogin}
          />
        </View>

        {/* Security & support */}
        <SectionHeader title="Security" theme={theme} />
        <View style={[styles.sectionGroup, { backgroundColor: theme.bg.surface }]}>
          <SettingsRow kind="navigation" theme={theme} label="Change password" onPress={onChangePassword} />
          <Divider theme={theme} />
          <SettingsRow kind="navigation" theme={theme} label="Privacy" onPress={onOpenPrivacy} />
          <Divider theme={theme} />
          <SettingsRow kind="navigation" theme={theme} label="Help & support" onPress={onOpenHelp} />
        </View>

        {/* Account actions */}
        <SectionHeader title="Account" theme={theme} />
        <View style={[styles.sectionGroup, { backgroundColor: theme.bg.surface }]}>
          <SettingsRow kind="navigation" theme={theme} label="Sign out" onPress={onSignOut} />
          <Divider theme={theme} />
          <SettingsRow
            kind="navigation"
            theme={theme}
            label="Delete account"
            destructive
            loading={isDeleting}
            disabled={isDeleting}
            onPress={confirmDelete}
            testID="delete-account-row"
          />
        </View>
      </ScrollView>
    </View>
  );
}

const styles = StyleSheet.create({
  flex: {
    flex: 1,
  },
  screenTitle: {
    fontSize: 28,
    fontWeight: '700',
    marginHorizontal: 16,
    marginBottom: 16,
  },
  profileRow: {
    flexDirection: 'row',
    alignItems: 'center',
    paddingHorizontal: 16,
    paddingVertical: 12,
    borderRadius: 12,
    marginHorizontal: 16,
  },
  profileText: {
    flex: 1,
    marginLeft: 12,
    marginRight: 8,
  },
  profileName: {
    fontSize: 17,
    fontWeight: '600',
  },
  profileEmail: {
    fontSize: 14,
    marginTop: 2,
  },
  chevron: {
    fontSize: 20,
  },
  sectionGroup: {
    borderRadius: 12,
    marginHorizontal: 16,
    overflow: 'hidden',
  },
});
```

**Usage** (wire up with real handlers/state, e.g. from your auth store):

```tsx
<AccountSettingsScreen
  user={{ name: 'Alex Rivera', email: 'alex@example.com' }}
  notificationsEnabled={notifications}
  biometricLoginEnabled={biometricLogin}
  onEditProfile={() => navigation.navigate('EditProfile')}
  onChangePassword={() => navigation.navigate('ChangePassword')}
  onChangeNotifications={setNotifications}
  onChangeBiometricLogin={setBiometricLogin}
  onOpenPrivacy={() => navigation.navigate('Privacy')}
  onOpenHelp={() => navigation.navigate('Help')}
  onSignOut={signOut}
  onDeleteAccount={() => api.deleteAccount()}
/>
```

One dependency assumption: `react-native-safe-area-context` (standard in nearly every RN app, required by react-navigation) for the `useSafeAreaInsets` hook. If your app doesn't have it, swap those insets for RN core's `SafeAreaView` on iOS and manual `StatusBar.currentHeight` handling on Android, though the context package is the more robust choice for edge-to-edge on both platforms.
